#include <SDL.h>
#include "render_device_api.hpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
static void check(bool ok,const char*m){if(!ok){fprintf(stderr,"FAIL: %s\n",m);exit(1);}}
int main(){
 setenv("STORM_METAL_PROFILE","1",1);check(SDL_Init(SDL_INIT_VIDEO)==0,SDL_GetError());auto*w=SDL_CreateWindow("FFP cache fixture",0,0,64,64,SDL_WINDOW_HIDDEN|SDL_WINDOW_METAL);check(w,SDL_GetError());storm_render::Presentation pp{};pp.width=pp.height=64;pp.colorFormat=storm_render::AssetFormat::A8R8G8B8;storm_render::Device*d=nullptr;check(storm_render::succeeded(storm_render::createMetalDevice(w, &pp, &d)),"device");
 struct V{float x,y,z,nx,ny,nz;uint32_t color;};V v[]={{-.8f,-.8f,.5f,0,0,-1,0xffff2020},{.8f,-.8f,.5f,0,0,-1,0xff20ff20},{-.8f,.8f,.5f,0,0,-1,0xff2020ff},{.8f,.8f,.5f,0,0,-1,0xffeeeeee}};uint16_t ix[]={0,1,2,2,1,3};
 d->SetFVF(storm_render::vertexFormat::xyz|storm_render::vertexFormat::normal|storm_render::vertexFormat::diffuse);d->SetRenderState(storm_render::RenderDepthTest,false);d->SetRenderState(storm_render::RenderLighting,false);d->SetRenderState(storm_render::RenderCullMode,storm_render::CullNone);d->SetTextureStageState(0,storm_render::StageColorOp,storm_render::TextureOpSelectArg1);d->SetTextureStageState(0,storm_render::StageColorArg1,storm_render::textureArg::diffuse);d->SetTextureStageState(1,storm_render::StageColorOp,storm_render::TextureOpDisable);
 storm_render::VertexBuffer*vb=nullptr;storm_render::IndexBuffer*ib=nullptr;d->CreateVertexBuffer(sizeof(v), 0, 0, &vb);d->CreateIndexBuffer(sizeof(ix), 0, storm_render::IndexFormat::UInt16, &ib);void*p=nullptr;
 auto uploadVB=[&](){check(storm_render::succeeded(vb->Lock(0,0,&p,0)),"VB lock");memcpy(p,v,sizeof(v));check(storm_render::succeeded(vb->Unlock()),"VB unlock");};auto uploadIB=[&](){check(storm_render::succeeded(ib->Lock(0,0,&p,0)),"IB lock");memcpy(p,ix,sizeof(ix));check(storm_render::succeeded(ib->Unlock()),"IB unlock");};uploadVB();uploadIB();
 storm_render::Surface*target=nullptr,*readback=nullptr;d->GetRenderTarget(&target);d->CreateOffscreenPlainSurface(64, 64, storm_render::AssetFormat::A8R8G8B8, &readback);
 auto render=[&](bool bound){d->Clear(storm_render::clear::color, 0xff102030, 1);d->BeginScene();if(bound){d->SetStreamSource(0,vb,0,sizeof(V));d->SetIndices(ib);check(storm_render::succeeded(d->DrawIndexedPrimitive(storm_render::PrimitiveTriangleList,0,0,4,0,2)),"bound draw");}else{V expanded[6];for(int i=0;i<6;i++)expanded[i]=v[ix[i]];check(storm_render::succeeded(d->DrawPrimitiveUP(storm_render::PrimitiveTriangleList,2,expanded,sizeof(V))),"UP reference");}d->EndScene();check(storm_render::succeeded(d->GetRenderTargetData(target,readback)),"readback");storm_render::LockedRect r{};check(storm_render::succeeded(readback->LockRect(&r,nullptr,storm_render::lock::readOnly)),"readback lock");std::vector<uint32_t> out(4096);for(int y=0;y<64;y++)memcpy(out.data()+64*y,(char*)r.pBits+y*r.Pitch,256);readback->UnlockRect();return out;};
 auto verify=[&](const char*why){auto reference=render(false);check(render(true)==reference,why);check(render(true)==reference,"repeat cache hit matches reference");};
 verify("initial source");storm_render::Matrix matrix{};for(int i=0;i<4;i++)matrix.m[i][i]=1;matrix.m[3][0]=.18f;d->SetTransform(storm_render::TransformView,&matrix);verify("view remains per draw");matrix.m[0][0]=.65f;matrix.m[3][0]=0;d->SetTransform(storm_render::TransformProjection,&matrix);verify("projection remains per draw");
 v[0].color=0xff00ffff;v[1].x=.3f;uploadVB();verify("same-frame VB mutation");ix[3]=0;ix[4]=2;ix[5]=3;uploadIB();verify("same-frame IB mutation");
 check(storm_render::succeeded(vb->Lock(0,0,&p,0)),"locked bypass");v[2].color=0xffffff00;memcpy(p,v,sizeof(v));verify("locked VB bypasses cached revision");v[2].color=0xffff00ff;memcpy(p,v,sizeof(v));verify("second locked edit bypasses cache");vb->Unlock();verify("unlock revision");
 check(storm_render::succeeded(ib->Lock(0,0,&p,0)),"locked IB bypass");ix[0]=3;memcpy(p,ix,sizeof(ix));verify("locked IB content changes");ib->Unlock();
 check(storm_render::succeeded(d->Present()),"present");verify("next frame arena reuse");
 target->Release();target=nullptr;check(storm_render::succeeded(d->Reset(&pp)),"reset");d->GetRenderTarget(&target);d->SetFVF(storm_render::vertexFormat::xyz|storm_render::vertexFormat::normal|storm_render::vertexFormat::diffuse);d->SetRenderState(storm_render::RenderDepthTest,false);d->SetRenderState(storm_render::RenderCullMode,storm_render::CullNone);d->SetTextureStageState(0,storm_render::StageColorOp,storm_render::TextureOpSelectArg1);d->SetTextureStageState(0,storm_render::StageColorArg1,storm_render::textureArg::diffuse);verify("reset cache invalidation");
 d->SetRenderState(storm_render::RenderLighting,true);storm_render::Material material{};material.Diffuse={.7f,.6f,.5f,1};material.Ambient={.2f,.2f,.2f,1};d->SetMaterial(&material);d->SetRenderState(storm_render::RenderAmbient,0xff404040);storm_render::Light light{};light.Type=storm_render::LightKind::Directional;light.Direction={0,0,1};light.Diffuse={.8f,.7f,.6f,1};d->SetLight(0,&light);d->LightEnable(0,true);verify("lit cache baseline");
 storm_render::Light stabilizedSun{};d->GetLight(0,&stabilizedSun);light.Direction.x=.00001f;d->SetLight(0,&light);storm_render::Light nearbySun{};d->GetLight(0,&nearbySun);check(memcmp(&stabilizedSun.Direction,&nearbySun.Direction,sizeof(storm_render::Vector3))==0,"subtexel sun motion shares the light and shadow source");verify("stabilized sun pixels");d->SetLight(1,&light);storm_render::Light secondary{};d->GetLight(1,&secondary);check(memcmp(&secondary.Direction,&light.Direction,sizeof(storm_render::Vector3))==0,"other directional lights retain original direction");
 matrix={};for(int i=0;i<4;i++)matrix.m[i][i]=1;matrix.m[3][0]=.125f;d->SetTransform(storm_render::TransformWorld,&matrix);light.Position={.125f,0,0};d->SetLight(0,&light);verify("camera-relative sun cache pixels");light.Direction={1,0,1};d->SetLight(0,&light);verify("sun direction invalidates cached colors");
 light.Type=storm_render::LightKind::Point;light.Position={0,0,-1};light.Range=10;light.Attenuation0=1;light.Attenuation1=.5f;d->SetLight(0,&light);verify("point light baseline");matrix.m[3][0]=.3f;d->SetTransform(storm_render::TransformWorld,&matrix);verify("point light world position invalidation");light.Position.x=.6f;d->SetLight(0,&light);verify("point light position invalidation");
 storm_render::VertexBuffer*dynamicVB=nullptr;check(storm_render::succeeded(d->CreateVertexBuffer(sizeof(v), storm_render::usage::dynamic|storm_render::usage::writeOnly, storm_render::vertexFormat::xyz|storm_render::vertexFormat::normal|storm_render::vertexFormat::diffuse, &dynamicVB)),"dynamic VB");storm_render::VertexBufferDesc dynamicDesc{};check(storm_render::succeeded(dynamicVB->GetDesc(&dynamicDesc))&&(dynamicDesc.Usage&storm_render::usage::dynamic)&&dynamicDesc.FVF==(storm_render::vertexFormat::xyz|storm_render::vertexFormat::normal|storm_render::vertexFormat::diffuse),"dynamic source metadata reaches cache admission");vb->Release();vb=dynamicVB;uploadVB();verify("dynamic source uses frame arena");v[0].x+=.05f;uploadVB();verify("dynamic source revision pixels");storm_render::IndexBuffer*dynamicIB=nullptr;check(storm_render::succeeded(d->CreateIndexBuffer(sizeof(ix), storm_render::usage::dynamic, storm_render::IndexFormat::UInt16, &dynamicIB)),"dynamic IB");storm_render::IndexBufferDesc indexDesc{};check(storm_render::succeeded(dynamicIB->GetDesc(&indexDesc))&&(indexDesc.Usage&storm_render::usage::dynamic),"dynamic index metadata reaches cache admission");dynamicIB->Release();
 puts("PASS: FFP cache pixels match UP across lit/unlit camera, light, VB/IB and locked mutations, Present and Reset");target->Release();readback->Release();vb->Release();ib->Release();d->Release();SDL_DestroyWindow(w);SDL_Quit();
}
